WITH remaining_keys AS (SELECT id, product_id FROM store_sales INTERSECT SELECT id, product_id FROM store_sales WHERE store_id IN (1, 2, 3, 5)), kept_rows AS (SELECT s.* FROM store_sales s INNER JOIN remaining_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT s.store_id, s.product_id, s.sale_date, s.units, s.revenue, (SELECT MIN(t2.quantity) FROM order_items t2 WHERE t2.product_id = s.product_id) AS min_order_item_quantity FROM kept_rows s ORDER BY sale_date NULLS LAST;
